using Robust.Shared.Prototypes;

namespace Content.Shared._VG.Fire;

/// <summary>
///     Whether the entity prototype of the same id burns as a vg13 flammable thing, and how. Children without an entry
///     of their own take their nearest listed parent's. Generated by Tools/_VG/flammable/gen_flammable.py.
/// </summary>
[Prototype("vgFlammable")]
public sealed partial class VgFlammablePrototype : IPrototype
{
    [IdDataField]
    public string ID { get; private set; } = default!;

    /// <summary>
    ///     False for what vg13 makes fireproof, so children of a fireproof thing don't inherit a burning parent's entry.
    /// </summary>
    [DataField]
    public bool Burns = true;

    [DataField]
    public ProtoId<VgThermalMaterialPrototype> Material = "Fabric";

    /// <summary>
    ///     vg13 thermal_mass, from its w_class.
    /// </summary>
    [DataField]
    public float ThermalMass = 0.1f;
}
